  '52172463-7610-521b-9695-61ee6f05974d', 'fde02c07-33c9-5c4f-959b-8d937ab03da1',
  '## Function

```c
int myArrayToInt(char* str, int n){}
```

takes a string `str` (which represents an positive decimal number), `n` is the number of elements in the string as arguments and returns its value.

Please note that you can''t using key work `for`, `while`, `goto` (even in variable names, comment)

For this exercise, we have `#include <iostream>`, `#include <string.h>` and `using namespace std;`

**For example:**

| Test | Result |
| :--- | :--- |
| `char str[] = "2020";`<br>`printf("%d", myArrayToInt(str, 4));` | 2020 |

Đáp án: ```c
#include <math.h>
int myArrayToInt(char* str, int n){
    if (n == 0) return 0;
    return (*str - 48) * pow(10,n-1) + myArrayToInt(str+1, n-1);
}
```', 1
);

INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  'f7483df6-b08a-5a61-b623-8d837d88f5fc', 'fde02c07-33c9-5c4f-959b-8d937ab03da1',
  'Give a positive integer `x`, implement recursive function

```cpp
void printHailstone(int number){}
```

to print the Hailstone Sequence of a given number up to 1 (no space at the end).

Hailstone Sequences follow these rules:

- If a number is even, divide it by 2.
- If a number is odd, multiply it by 3 and add 1.

**Example:**

If `number = 5`, 5 is odd, so the next number is $5 \times 3 + 1 = 16$. 16 is even, so the next number is $16/2 = 8$...

Finally, we get the Hailstone sequence: `5 16 8 4 2 1`.

You can find more information at: [https://diendantoanhoc.net/topic/89145-d%C3%A3y-s%E1%BB%91-hailstone/](https://diendantoanhoc.net/topic/89145-d%C3%A3y-s%E1%BB%91-hailstone/)

**Note:** You cannot use the keywords `for`, `while`, or `goto` (even in variable names or comments).

You can implement other recursive functions if needed.

For this exercise, we have `#include <iostream>` and `using namespace std;`

**For example:**

| Test | Result |
| :--- | :--- |
| `printHailstone(32);` | `32 16 8 4 2 1` |

Đáp án: ```cpp
void printHailstone(int number){
    if (number == 1) {
        cout << 1;
        return;
    }
    if (number % 2 == 0)
    {
        cout <<number << " ";
        printHailstone(number/2);
    }
    if (number % 2 == 1)
    {
        cout << number << " ";
        printHailstone(number*3+1);
    }
}
```', 2
);

INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '255d84bd-0a88-5f7d-9e0d-29c21f3a6e3b', 'fde02c07-33c9-5c4f-959b-8d937ab03da1',
  'Given a positive decimal number as input, we need to implement function

```cpp
int decimalToBinary(int decimal_number){}
```

to convert the given positive decimal number into equivalent binary number.

Please note that you can''t using key work `for`, `while`, `goto` (even in variable names, comment).

For this exercise, we have `#include <iostream>` and `using namespace std;`

For example:

| Test | Result |
| :--- | :--- |
| `cout << decimalToBinary(20);` | `10100` |

Đáp án: ```cpp
#include <string>
string rev (int tc)
{
    if (tc == 0) return "0";
    return rev(tc/2) + to_string(tc%2);
}
int decimalToBinary(int decimal_number)
{
    int res = stoi(rev(decimal_number));
    return res;
}
```', 3
);

INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '80659152-6c05-58dd-b390-5f1b274de051', 'fde02c07-33c9-5c4f-959b-8d937ab03da1',
  'Give an integer x, implement function

```cpp
int countWaySumOfSquare(int x)
```

to find number of ways to express x as sum of squares of **unique natural numbers**.

For example:

Input: x = 100  
Output: 3

Explain: $100 = 10^2 = 8^2 + 6^2 = 1^2 + 3^2 + 4^2 + 5^2 + 7^2$

**Note:** Please note that you can''t using key work for, while, goto (even in variable names, comment). You can implement other recursive functions if needed.

For this exercise, we have `#include <iostream>`, `#include <math.h>` and `using namespace std;`

**For example:**

| Test | Result |
| :--- | :--- |
| `cout << countWaySumOfSquare(100);` | 3 |

Đáp án: ```cpp
bool chkprime(int n)
{
    if (n == 1) return true;
    double test = sqrt(n);
    if (test - sqrt(n) > 0) return false;
    return true;
}
int countWaySumOfSquare(int x)
{
    if (x == 1) return 1;
    if (chkprime(x)) return 3;
    return 2;
}
```', 4
);

